<?php
declare(strict_types=1);

function mg_investment_closing_round(PDO $pdo,string $publicId): array
{
    return mg_investment_pipeline_round($pdo,$publicId);
}

function mg_investment_closing_sync(PDO $pdo,?int $actorUserId=null): array
{
    $profiles=$pdo->prepare("INSERT INTO investment_closing_profiles
      (public_id,round_id,stage,readiness_score,counsel_status,board_status,created_by_user_id,updated_by_user_id,created_at,updated_at)
      SELECT UUID(),r.id,'planning',0,
             CASE WHEN r.counsel_status='approved' THEN 'approved' WHEN r.counsel_status='requested' THEN 'requested' ELSE 'not_started' END,
             'not_started',?,?,NOW(),NOW()
      FROM investment_rounds r
      LEFT JOIN investment_closing_profiles cp ON cp.round_id=r.id
      WHERE cp.id IS NULL");
    $profiles->execute([$actorUserId,$actorUserId]);

    $records=$pdo->prepare("INSERT INTO investor_closing_records
      (public_id,round_id,investor_user_id,status,instrument_type,proposed_amount_cents,final_amount_cents,signed_amount_cents,reported_funded_cents,verified_funded_cents,created_by_user_id,updated_by_user_id,created_at,updated_at)
      SELECT UUID(),ri.round_id,ri.investor_user_id,
        CASE ri.status WHEN 'soft_committed' THEN 'soft_committed' WHEN 'signed' THEN 'signed' WHEN 'funded' THEN 'funds_verified' ELSE 'interested' END,
        CASE r.instrument_type WHEN 'post_money_safe' THEN 'post_money_safe' WHEN 'convertible_note' THEN 'convertible_note' WHEN 'priced_equity' THEN 'priced_equity' ELSE 'not_finalized' END,
        ri.indicated_interest_cents,GREATEST(ri.soft_commitment_cents,ri.signed_cents),ri.signed_cents,ri.funded_cents,ri.funded_cents,?,?,NOW(),NOW()
      FROM investor_round_interests ri
      INNER JOIN investment_rounds r ON r.id=ri.round_id
      LEFT JOIN investor_closing_records cr ON cr.round_id=ri.round_id AND cr.investor_user_id=ri.investor_user_id
      WHERE cr.id IS NULL AND ri.status NOT IN ('passed','declined','archived')");
    $records->execute([$actorUserId,$actorUserId]);
    return ['profiles_created'=>$profiles->rowCount(),'records_created'=>$records->rowCount()];
}

function mg_investment_closing_record(PDO $pdo,string $publicId,bool $lock=false): array
{
    $sql='SELECT cr.*,r.public_id AS round_public_id,r.public_name,r.status AS round_status,u.full_name,u.display_name,u.email,ip.firm_name,b.public_id AS batch_public_id,b.batch_name,b.status AS batch_status
          FROM investor_closing_records cr
          INNER JOIN investment_rounds r ON r.id=cr.round_id
          INNER JOIN users u ON u.id=cr.investor_user_id
          LEFT JOIN investor_profiles ip ON ip.user_id=cr.investor_user_id
          LEFT JOIN investment_closing_batches b ON b.id=cr.batch_id
          WHERE cr.public_id=? LIMIT 1';
    if($lock)$sql.=' FOR UPDATE';
    $stmt=$pdo->prepare($sql);$stmt->execute([$publicId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);
    if(!$row)throw new MgInvestmentException('Investor closing record not found.',404);
    return $row;
}

function mg_investment_closing_event(PDO $pdo,int $recordId,?int $actorUserId,string $eventType,?string $fromStatus=null,?string $toStatus=null,?int $amountCents=null,array $details=[]): void
{
    $allowed=['created','status_changed','terms_updated','documents_sent','signature_reported','funding_reported','funding_verified','batch_assigned','closing_completed','adjustment','note'];
    if(!in_array($eventType,$allowed,true))throw new MgInvestmentException('Invalid closing event type.');
    $stmt=$pdo->prepare('INSERT INTO investor_closing_events (public_id,closing_record_id,actor_user_id,event_type,from_status,to_status,amount_cents,details_json,created_at) VALUES (?,?,?,?,?,?,?,?,NOW())');
    $stmt->execute([mg_investment_uuid(),$recordId,$actorUserId,$eventType,$fromStatus,$toStatus,$amountCents,$details?mg_investment_json_encode($details):null]);
}

function mg_investment_closing_dashboard(PDO $pdo,array $filters=[]): array
{
    mg_investment_closing_sync($pdo);
    $roundPublicId=trim((string)($filters['round_id']??''));$roundId=null;
    if($roundPublicId!=='')$roundId=(int)mg_investment_closing_round($pdo,$roundPublicId)['id'];
    $rounds=$pdo->query('SELECT r.public_id,r.public_name,r.status,r.instrument_type,r.minimum_raise_cents,r.target_raise_cents,r.maximum_raise_cents,r.signed_cents,r.funded_cents,r.counsel_status,cp.stage AS closing_stage,cp.readiness_score,cp.planned_first_close_at,cp.planned_final_close_at FROM investment_rounds r LEFT JOIN investment_closing_profiles cp ON cp.round_id=r.id ORDER BY r.updated_at DESC')->fetchAll(PDO::FETCH_ASSOC);
    $admins=$pdo->query('SELECT DISTINCT u.id,u.full_name,u.email FROM users u INNER JOIN user_roles ur ON ur.user_id=u.id INNER JOIN roles r ON r.id=ur.role_id WHERE r.slug IN ("admin","super_admin") ORDER BY u.full_name')->fetchAll(PDO::FETCH_ASSOC);
    $params=[];$where='';if($roundId!==null){$where=' WHERE cr.round_id=?';$params[]=$roundId;}
    $stmt=$pdo->prepare('SELECT cr.*,r.public_id AS round_public_id,r.public_name,u.full_name,u.display_name,u.email,ip.firm_name,b.public_id AS batch_public_id,b.batch_name,
      ob.kyc_status,ob.accreditation_status,ob.counsel_status AS onboarding_counsel_status,
      (SELECT COUNT(*) FROM investment_closing_packets p WHERE p.round_id=cr.round_id AND p.investor_user_id=cr.investor_user_id) AS packet_count,
      (SELECT COUNT(*) FROM investment_financial_verification_requests vr WHERE vr.closing_record_id=cr.id AND vr.status="pending") AS pending_verifications
      FROM investor_closing_records cr INNER JOIN investment_rounds r ON r.id=cr.round_id INNER JOIN users u ON u.id=cr.investor_user_id LEFT JOIN investor_profiles ip ON ip.user_id=cr.investor_user_id LEFT JOIN investment_closing_batches b ON b.id=cr.batch_id LEFT JOIN investor_onboarding_reviews ob ON ob.round_id=cr.round_id AND ob.investor_user_id=cr.investor_user_id'.$where.' ORDER BY FIELD(cr.status,"funds_reported","funding_pending","signed","investor_reviewing","documents_sent","documents_requested","soft_committed","interested","funds_verified","included_in_closing","closing_complete","withdrawn","declined"),cr.updated_at DESC');$stmt->execute($params);$records=$stmt->fetchAll(PDO::FETCH_ASSOC);
    $whereB=$roundId!==null?' WHERE b.round_id='.(int)$roundId:'';
    $batches=$pdo->query('SELECT b.*,r.public_id AS round_public_id,r.public_name,(SELECT COUNT(*) FROM investment_closing_batch_investors bi WHERE bi.batch_id=b.id) AS investor_count FROM investment_closing_batches b INNER JOIN investment_rounds r ON r.id=b.round_id'.$whereB.' ORDER BY r.updated_at DESC,b.sequence_number')->fetchAll(PDO::FETCH_ASSOC);
    $whereC=$roundId!==null?' WHERE c.round_id='.(int)$roundId:'';
    $compliance=$pdo->query('SELECT c.*,r.public_id AS round_public_id,r.public_name,u.full_name AS assigned_name FROM investment_compliance_requirements c INNER JOIN investment_rounds r ON r.id=c.round_id LEFT JOIN users u ON u.id=c.assigned_user_id'.$whereC.' ORDER BY FIELD(c.status,"overdue","changes_required","in_progress","requested","not_started","filed","confirmed","approved","not_applicable"),COALESCE(c.due_at,"2999-12-31"),c.id')->fetchAll(PDO::FETCH_ASSOC);
    $whereV=$roundId!==null?' WHERE vr.round_id='.(int)$roundId:'';
    $verifications=$pdo->query('SELECT vr.*,cr.public_id AS closing_record_public_id,r.public_id AS round_public_id,r.public_name,u.full_name,u.display_name,u.email,s.full_name AS submitted_by_name,d.decision,d.decision_notes,rv.full_name AS reviewer_name FROM investment_financial_verification_requests vr INNER JOIN investor_closing_records cr ON cr.id=vr.closing_record_id INNER JOIN investment_rounds r ON r.id=vr.round_id INNER JOIN users u ON u.id=cr.investor_user_id INNER JOIN users s ON s.id=vr.submitted_by_user_id LEFT JOIN investment_financial_verification_decisions d ON d.request_id=vr.id LEFT JOIN users rv ON rv.id=d.reviewer_user_id'.$whereV.' ORDER BY FIELD(vr.status,"pending","approved","rejected","cancelled"),vr.submitted_at DESC')->fetchAll(PDO::FETCH_ASSOC);
    $whereP=$roundId!==null?' WHERE p.round_id='.(int)$roundId:'';
    $packets=$pdo->query('SELECT p.*,r.public_id AS round_public_id,r.public_name,u.full_name,u.display_name,u.email,(SELECT COUNT(*) FROM investment_closing_documents d WHERE d.packet_id=p.id) AS document_count FROM investment_closing_packets p INNER JOIN investment_rounds r ON r.id=p.round_id INNER JOIN users u ON u.id=p.investor_user_id'.$whereP.' ORDER BY p.updated_at DESC')->fetchAll(PDO::FETCH_ASSOC);
    $whereR=$roundId!==null?' WHERE rp.round_id='.(int)$roundId:'';
    $reports=$pdo->query('SELECT rp.*,r.public_id AS round_public_id,r.public_name,(SELECT MAX(version_number) FROM investment_reporting_snapshots s WHERE s.reporting_period_id=rp.id) AS latest_version FROM investment_reporting_periods rp INNER JOIN investment_rounds r ON r.id=rp.round_id'.$whereR.' ORDER BY rp.starts_at DESC')->fetchAll(PDO::FETCH_ASSOC);
    $summary=['investors'=>count($records),'awaiting_documents'=>0,'signed'=>0,'funding_pending'=>0,'funds_reported'=>0,'funds_verified'=>0,'closing_complete'=>0,'pending_verifications'=>0,'open_compliance'=>0,'overdue_compliance'=>0,'verified_funded_cents'=>0,'readiness_score'=>0];
    foreach($records as $row){if(in_array($row['status'],['documents_requested','documents_sent','investor_reviewing'],true))$summary['awaiting_documents']++;if((int)$row['signed_amount_cents']>0)$summary['signed']++;if($row['status']==='funding_pending')$summary['funding_pending']++;if($row['status']==='funds_reported')$summary['funds_reported']++;if((int)$row['verified_funded_cents']>0)$summary['funds_verified']++;if($row['status']==='closing_complete')$summary['closing_complete']++;$summary['pending_verifications']+=(int)$row['pending_verifications'];$summary['verified_funded_cents']+=(int)$row['verified_funded_cents'];}
    foreach($compliance as $row){if(!in_array($row['status'],['confirmed','approved','not_applicable'],true))$summary['open_compliance']++;if($row['status']==='overdue'||(!empty($row['due_at'])&&strtotime((string)$row['due_at'])<time()&&!in_array($row['status'],['confirmed','approved','not_applicable'],true)))$summary['overdue_compliance']++;}
    if($roundId!==null){$q=$pdo->prepare('SELECT readiness_score FROM investment_closing_profiles WHERE round_id=?');$q->execute([$roundId]);$summary['readiness_score']=(int)$q->fetchColumn();}
    return compact('rounds','admins','records','batches','compliance','verifications','packets','reports','summary');
}

function mg_investment_closing_save_profile(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));
    $stages=['planning','pre_closing_review','documents_ready','investor_signing','funding_pending','rolling_close','final_close','post_close_review','complete','paused','cancelled'];$review=['not_started','requested','in_review','approved','changes_required','not_applicable'];$stage=(string)($input['stage']??'planning');$counsel=(string)($input['counsel_status']??'not_started');$board=(string)($input['board_status']??'not_started');if(!in_array($stage,$stages,true)||!in_array($counsel,$review,true)||!in_array($board,$review,true))throw new MgInvestmentException('Invalid closing, counsel, or board status.');
    $score=max(0,min(100,(int)($input['readiness_score']??0)));$actorId=(int)$actor['id'];$blockers=is_array($input['blockers']??null)?array_values(array_filter(array_map(static fn($v)=>mg_investment_text($v,500),$input['blockers']))):[];
    $stmt=$pdo->prepare('INSERT INTO investment_closing_profiles (public_id,round_id,stage,readiness_score,counsel_status,board_status,planned_first_close_at,planned_final_close_at,actual_final_close_at,blockers_json,closing_notes,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE stage=VALUES(stage),readiness_score=VALUES(readiness_score),counsel_status=VALUES(counsel_status),board_status=VALUES(board_status),planned_first_close_at=VALUES(planned_first_close_at),planned_final_close_at=VALUES(planned_final_close_at),actual_final_close_at=VALUES(actual_final_close_at),blockers_json=VALUES(blockers_json),closing_notes=VALUES(closing_notes),updated_by_user_id=VALUES(updated_by_user_id),updated_at=NOW()');
    $stmt->execute([mg_investment_uuid(),(int)$round['id'],$stage,$score,$counsel,$board,mg_investment_date($input['planned_first_close_at']??null),mg_investment_date($input['planned_final_close_at']??null),mg_investment_date($input['actual_final_close_at']??null),$blockers?mg_investment_json_encode($blockers):null,mg_investment_long_text($input['closing_notes']??'',12000)?:null,$actorId,$actorId]);
    mg_audit('investment_closing_profile_saved','investment_round',['round_id'=>$round['public_id'],'stage'=>$stage,'readiness_score'=>$score],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);
}

function mg_investment_closing_save_record(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$record=mg_investment_closing_record($pdo,mg_investment_text($input['record_id']??'',36,36,'Closing record identifier'),true);$actorId=(int)$actor['id'];
    $statuses=['interested','soft_committed','documents_requested','documents_sent','investor_reviewing','signed','funding_pending','funds_reported','funds_verified','included_in_closing','closing_complete','withdrawn','declined'];$instruments=['not_finalized','post_money_safe','convertible_note','priced_equity','other'];$status=(string)($input['status']??$record['status']);$instrument=(string)($input['instrument_type']??$record['instrument_type']);if(!in_array($status,$statuses,true)||!in_array($instrument,$instruments,true))throw new MgInvestmentException('Invalid closing status or instrument type.');
    if(in_array($status,['signed','funding_pending','funds_reported','funds_verified','included_in_closing','closing_complete'],true)&&(int)$record['signed_amount_cents']<1)throw new MgInvestmentException('A verified signed amount is required for this closing status.',409);
    if(in_array($status,['funds_verified','included_in_closing','closing_complete'],true)&&(int)$record['verified_funded_cents']<1)throw new MgInvestmentException('Verified funded money is required for this closing status.',409);
    $batchId=null;if(!empty($input['batch_id'])){$q=$pdo->prepare('SELECT id,locked_at FROM investment_closing_batches WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($input['batch_id'],36,36,'Batch identifier'),(int)$record['round_id']]);$batch=$q->fetch(PDO::FETCH_ASSOC);if(!$batch)throw new MgInvestmentException('Closing batch not found.',404);if($batch['locked_at']!==null)throw new MgInvestmentException('Completed closing batches are immutable.',409);$batchId=(int)$batch['id'];}
    $oldStatus=(string)$record['status'];$stmt=$pdo->prepare('UPDATE investor_closing_records SET batch_id=?,status=?,instrument_type=?,proposed_amount_cents=?,final_amount_cents=?,agreement_reference=?,funding_reference=?,documents_sent_at=?,investor_signed_at=?,company_countersigned_at=?,funds_reported_at=?,closing_completed_at=IF(?="closing_complete",COALESCE(closing_completed_at,NOW()),closing_completed_at),internal_notes=?,updated_by_user_id=?,updated_at=NOW() WHERE id=?');
    $stmt->execute([$batchId,$status,$instrument,mg_investment_money($input['proposed_amount']??((int)$record['proposed_amount_cents']/100)),mg_investment_money($input['final_amount']??((int)$record['final_amount_cents']/100)),mg_investment_text($input['agreement_reference']??'',220)?:null,mg_investment_text($input['funding_reference']??'',220)?:null,mg_investment_date($input['documents_sent_at']??null),mg_investment_date($input['investor_signed_at']??null),mg_investment_date($input['company_countersigned_at']??null),mg_investment_date($input['funds_reported_at']??null),$status,mg_investment_long_text($input['internal_notes']??'',12000)?:null,$actorId,(int)$record['id']]);
    if($oldStatus!==$status)mg_investment_closing_event($pdo,(int)$record['id'],$actorId,'status_changed',$oldStatus,$status,null,['reason'=>mg_investment_text($input['change_reason']??'',500)]);
    mg_investment_closing_event($pdo,(int)$record['id'],$actorId,'terms_updated',$oldStatus,$status,null,['instrument_type'=>$instrument,'agreement_reference'=>mg_investment_text($input['agreement_reference']??'',220)]);
    $pipelineStage=['soft_committed'=>'soft_committed','signed'=>'signed','funds_verified'=>'funded','included_in_closing'=>'funded','closing_complete'=>'funded','withdrawn'=>'passed','declined'=>'declined'][$status]??null;if($pipelineStage)$pdo->prepare('UPDATE investor_pipeline_records SET stage=?,updated_by_user_id=?,updated_at=NOW() WHERE investor_user_id=?')->execute([$pipelineStage,$actorId,(int)$record['investor_user_id']]);
    mg_investment_pipeline_activity($pdo,(int)$record['investor_user_id'],(int)$record['round_id'],'status_change','Closing status updated',mg_investment_readable_stage($oldStatus).' → '.mg_investment_readable_stage($status),$actorId,['closing_record_id'=>$record['public_id']]);mg_audit('investor_closing_record_saved','investor_closing',['record_id'=>$record['public_id'],'status'=>$status],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$record['round_public_id']]);
}

function mg_investment_closing_save_batch(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$publicId=trim((string)($input['batch_id']??''));$statuses=['planning','review','ready','closing','completed','reopened','cancelled'];$review=['not_started','in_review','approved','changes_required','not_applicable'];$status=(string)($input['status']??'planning');$counsel=(string)($input['counsel_status']??'not_started');$board=(string)($input['board_status']??'not_started');if(!in_array($status,$statuses,true)||!in_array($counsel,$review,true)||!in_array($board,$review,true))throw new MgInvestmentException('Invalid batch status.');$actorId=(int)$actor['id'];
    if($publicId===''){$publicId=mg_investment_uuid();$sequence=(int)($input['sequence_number']??0);if($sequence<1){$q=$pdo->prepare('SELECT COALESCE(MAX(sequence_number),0)+1 FROM investment_closing_batches WHERE round_id=?');$q->execute([(int)$round['id']]);$sequence=(int)$q->fetchColumn();}$stmt=$pdo->prepare('INSERT INTO investment_closing_batches (public_id,round_id,batch_name,sequence_number,status,planned_close_at,counsel_status,board_status,notes,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$stmt->execute([$publicId,(int)$round['id'],mg_investment_text($input['batch_name']??'',180,2,'Batch name'),$sequence,$status,mg_investment_date($input['planned_close_at']??null),$counsel,$board,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,$actorId]);}
    else{$q=$pdo->prepare('SELECT * FROM investment_closing_batches WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($publicId,36,36,'Batch identifier'),(int)$round['id']]);$batch=$q->fetch(PDO::FETCH_ASSOC);if(!$batch)throw new MgInvestmentException('Closing batch not found.',404);if($batch['locked_at']!==null)throw new MgInvestmentException('Completed closing batches are immutable. Reopen with a separately audited action.',409);$pdo->prepare('UPDATE investment_closing_batches SET batch_name=?,sequence_number=?,status=?,planned_close_at=?,counsel_status=?,board_status=?,notes=?,updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([mg_investment_text($input['batch_name']??'',180,2,'Batch name'),max(1,(int)($input['sequence_number']??$batch['sequence_number'])),$status,mg_investment_date($input['planned_close_at']??null),$counsel,$board,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,(int)$batch['id']]);}
    mg_audit('investment_closing_batch_saved','investment_closing_batch',['batch_id'=>$publicId,'round_id'=>$round['public_id'],'status'=>$status],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);
}

function mg_investment_closing_assign_batch(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$record=mg_investment_closing_record($pdo,mg_investment_text($input['record_id']??'',36,36,'Closing record identifier'),true);$q=$pdo->prepare('SELECT * FROM investment_closing_batches WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($input['batch_id']??'',36,36,'Batch identifier'),(int)$record['round_id']]);$batch=$q->fetch(PDO::FETCH_ASSOC);if(!$batch)throw new MgInvestmentException('Closing batch not found.',404);if($batch['locked_at']!==null)throw new MgInvestmentException('Completed closing batches are immutable.',409);$amount=mg_investment_money($input['included_amount']??((int)$record['verified_funded_cents']/100));if($amount>(int)$record['verified_funded_cents'])throw new MgInvestmentException('Batch amount cannot exceed verified funded money.');$actorId=(int)$actor['id'];
    $pdo->prepare('INSERT INTO investment_closing_batch_investors (batch_id,closing_record_id,included_amount_cents,added_by_user_id,created_at) VALUES (?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE included_amount_cents=VALUES(included_amount_cents),added_by_user_id=VALUES(added_by_user_id)')->execute([(int)$batch['id'],(int)$record['id'],$amount,$actorId]);$pdo->prepare('UPDATE investor_closing_records SET batch_id=?,status=IF(verified_funded_cents>0,"included_in_closing",status),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([(int)$batch['id'],$actorId,(int)$record['id']]);$pdo->prepare('UPDATE investment_closing_batches SET included_amount_cents=(SELECT COALESCE(SUM(included_amount_cents),0) FROM investment_closing_batch_investors WHERE batch_id=?),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([(int)$batch['id'],$actorId,(int)$batch['id']]);mg_investment_closing_event($pdo,(int)$record['id'],$actorId,'batch_assigned',(string)$record['status'],(int)$record['verified_funded_cents']>0?'included_in_closing':(string)$record['status'],$amount,['batch_id'=>$batch['public_id'],'batch_name'=>$batch['batch_name']]);mg_audit('investor_closing_batch_assigned','investor_closing',['record_id'=>$record['public_id'],'batch_id'=>$batch['public_id'],'amount_cents'=>$amount],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$record['round_public_id']]);
}

function mg_investment_closing_complete_batch(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$batchId=mg_investment_text($input['batch_id']??'',36,36,'Batch identifier');$reason=mg_investment_long_text($input['completion_reason']??'',2000,10,'Completion reason');$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT b.*,r.public_id AS round_public_id FROM investment_closing_batches b INNER JOIN investment_rounds r ON r.id=b.round_id WHERE b.public_id=? LIMIT 1 FOR UPDATE');$q->execute([$batchId]);$batch=$q->fetch(PDO::FETCH_ASSOC);if(!$batch)throw new MgInvestmentException('Closing batch not found.',404);if($batch['locked_at']!==null)throw new MgInvestmentException('Closing batch is already complete.',409);if($batch['counsel_status']!=='approved'||$batch['board_status']!=='approved')throw new MgInvestmentException('Counsel and board status must be approved before completing a closing batch.',409);$check=$pdo->prepare('SELECT COUNT(*) AS total,SUM(cr.verified_funded_cents<1) AS unverified,SUM(CASE WHEN EXISTS(SELECT 1 FROM investment_closing_packets p WHERE p.round_id=cr.round_id AND p.investor_user_id=cr.investor_user_id AND p.status<>"complete") THEN 1 ELSE 0 END) AS incomplete_packets,COALESCE(SUM(bi.included_amount_cents),0) AS included FROM investment_closing_batch_investors bi INNER JOIN investor_closing_records cr ON cr.id=bi.closing_record_id WHERE bi.batch_id=?');$check->execute([(int)$batch['id']]);$state=$check->fetch(PDO::FETCH_ASSOC)?:[];if((int)($state['total']??0)<1)throw new MgInvestmentException('Add at least one investor before completing a closing batch.',409);if((int)($state['unverified']??0)>0)throw new MgInvestmentException('All included investors require verified funded money.',409);if((int)($state['incomplete_packets']??0)>0)throw new MgInvestmentException('All included investor document packets must be complete.',409);$actorId=(int)$actor['id'];$pdo->prepare('UPDATE investment_closing_batches SET status="completed",included_amount_cents=?,actual_close_at=NOW(),locked_at=NOW(),locked_by_user_id=?,updated_by_user_id=?,updated_at=NOW(),notes=CONCAT(COALESCE(notes,""),"\nCompletion: ",?) WHERE id=?')->execute([(int)$state['included'],$actorId,$actorId,$reason,(int)$batch['id']]);$records=$pdo->prepare('SELECT cr.id,cr.investor_user_id,cr.status FROM investment_closing_batch_investors bi INNER JOIN investor_closing_records cr ON cr.id=bi.closing_record_id WHERE bi.batch_id=?');$records->execute([(int)$batch['id']]);foreach($records->fetchAll(PDO::FETCH_ASSOC) as $record){$pdo->prepare('UPDATE investor_closing_records SET status="closing_complete",closing_completed_at=NOW(),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$actorId,(int)$record['id']]);mg_investment_closing_event($pdo,(int)$record['id'],$actorId,'closing_completed',(string)$record['status'],'closing_complete',null,['batch_id'=>$batchId,'reason'=>$reason]);mg_investment_pipeline_activity($pdo,(int)$record['investor_user_id'],(int)$batch['round_id'],'commitment_update','Investor closing completed',$reason,$actorId,['batch_id'=>$batchId]);}$pdo->commit();mg_audit('investment_closing_batch_completed','investment_closing_batch',['batch_id'=>$batchId,'included_amount_cents'=>(int)$state['included']],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$batch['round_public_id']]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}

function mg_investment_closing_reopen_batch(PDO $pdo,array $actor,array $input): array
{
    if(!mg_investment_is_super($actor))throw new MgInvestmentException('Only Super Admin can reopen a completed closing batch.',403);$reason=mg_investment_long_text($input['reason']??'',2000,10,'Reopen reason');$q=$pdo->prepare('SELECT b.*,r.public_id AS round_public_id FROM investment_closing_batches b INNER JOIN investment_rounds r ON r.id=b.round_id WHERE b.public_id=? LIMIT 1');$q->execute([mg_investment_text($input['batch_id']??'',36,36,'Batch identifier')]);$batch=$q->fetch(PDO::FETCH_ASSOC);if(!$batch)throw new MgInvestmentException('Closing batch not found.',404);if($batch['locked_at']===null)throw new MgInvestmentException('Only completed batches can be reopened.',409);$pdo->prepare('UPDATE investment_closing_batches SET status="reopened",locked_at=NULL,locked_by_user_id=NULL,actual_close_at=NULL,notes=CONCAT(COALESCE(notes,""),"\nReopened: ",?),updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$reason,(int)$actor['id'],(int)$batch['id']]);mg_audit('investment_closing_batch_reopened','investment_closing_batch',['batch_id'=>$batch['public_id'],'reason'=>$reason],(int)$actor['id']);return mg_investment_closing_dashboard($pdo,['round_id'=>$batch['round_public_id']]);
}

function mg_investment_onboarding_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$userId=(int)($input['investor_user_id']??0);if($userId<1)throw new MgInvestmentException('Select an investor.');$entity=(string)($input['investor_entity_type']??'individual');$tax=['not_requested','requested','received','reviewed','expired','not_applicable'];$bo=['not_requested','requested','received','reviewed','issues_found','not_applicable'];$kyc=['not_started','submitted_external','pending_external','passed_external','failed_external','expired','not_applicable'];$acc=['not_started','submitted_external','pending_external','verified_external','not_verified','expired','not_required'];$counsel=['not_started','in_review','approved','changes_required','not_applicable'];if(!in_array($entity,['individual','entity','trust','fund','other'],true)||!in_array($input['tax_document_status']??'not_requested',$tax,true)||!in_array($input['beneficial_owner_status']??'not_requested',$bo,true)||!in_array($input['kyc_status']??'not_started',$kyc,true)||!in_array($input['accreditation_status']??'not_started',$acc,true)||!in_array($input['counsel_status']??'not_started',$counsel,true))throw new MgInvestmentException('Invalid onboarding review status.');$actorId=(int)$actor['id'];$stmt=$pdo->prepare('INSERT INTO investor_onboarding_reviews (public_id,round_id,investor_user_id,investor_entity_type,legal_name,organization_name,authorized_signatory,tax_country,tax_document_status,beneficial_owner_status,kyc_status,kyc_provider_reference,accreditation_status,accreditation_provider,accreditation_reviewed_at,accreditation_expires_at,counsel_status,restriction_notes,reviewed_by_user_id,reviewed_at,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE investor_entity_type=VALUES(investor_entity_type),legal_name=VALUES(legal_name),organization_name=VALUES(organization_name),authorized_signatory=VALUES(authorized_signatory),tax_country=VALUES(tax_country),tax_document_status=VALUES(tax_document_status),beneficial_owner_status=VALUES(beneficial_owner_status),kyc_status=VALUES(kyc_status),kyc_provider_reference=VALUES(kyc_provider_reference),accreditation_status=VALUES(accreditation_status),accreditation_provider=VALUES(accreditation_provider),accreditation_reviewed_at=VALUES(accreditation_reviewed_at),accreditation_expires_at=VALUES(accreditation_expires_at),counsel_status=VALUES(counsel_status),restriction_notes=VALUES(restriction_notes),reviewed_by_user_id=VALUES(reviewed_by_user_id),reviewed_at=NOW(),updated_by_user_id=VALUES(updated_by_user_id),updated_at=NOW()');$stmt->execute([mg_investment_uuid(),(int)$round['id'],$userId,$entity,mg_investment_text($input['legal_name']??'',220,2,'Legal name'),mg_investment_text($input['organization_name']??'',220)?:null,mg_investment_text($input['authorized_signatory']??'',220)?:null,mg_investment_text($input['tax_country']??'',120)?:null,$input['tax_document_status']??'not_requested',$input['beneficial_owner_status']??'not_requested',$input['kyc_status']??'not_started',mg_investment_text($input['kyc_provider_reference']??'',220)?:null,$input['accreditation_status']??'not_started',mg_investment_text($input['accreditation_provider']??'',220)?:null,mg_investment_date($input['accreditation_reviewed_at']??null),mg_investment_date($input['accreditation_expires_at']??null),$input['counsel_status']??'not_started',mg_investment_long_text($input['restriction_notes']??'',8000)?:null,$actorId,$actorId,$actorId]);mg_audit('investor_onboarding_review_saved','investor_onboarding',['round_id'=>$round['public_id'],'investor_user_id'=>$userId],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);
}

function mg_investment_packet_recalculate(PDO $pdo,int $packetId): void
{
    $q=$pdo->prepare('SELECT SUM(required_document=1) AS required_count,SUM(required_document=1 AND status IN ("executed","complete","not_applicable")) AS completed_count,COUNT(*) AS total_count,SUM(status NOT IN ("executed","complete","not_applicable")) AS incomplete FROM investment_closing_documents WHERE packet_id=?');$q->execute([$packetId]);$c=$q->fetch(PDO::FETCH_ASSOC)?:[];$status=(int)($c['total_count']??0)>0&&(int)($c['incomplete']??0)===0?'complete':null;$sql='UPDATE investment_closing_packets SET required_document_count=?,completed_document_count=?,status=IF(?="complete","complete",IF(status="complete","assembling",status)),completed_at=IF(?="complete",COALESCE(completed_at,NOW()),NULL),updated_at=NOW() WHERE id=?';$pdo->prepare($sql)->execute([(int)($c['required_count']??0),(int)($c['completed_count']??0),$status,$status,$packetId]);
}

function mg_investment_packet_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$round=mg_investment_closing_round($pdo,mg_investment_text($input['round_id']??'',36,36,'Round identifier'));$userId=(int)($input['investor_user_id']??0);if($userId<1)throw new MgInvestmentException('Select an investor.');$status=(string)($input['status']??'draft');if(!in_array($status,['draft','assembling','investor_review','company_review','counsel_review','complete','archived'],true))throw new MgInvestmentException('Invalid packet status.');$publicId=trim((string)($input['packet_id']??''));$actorId=(int)$actor['id'];if($publicId===''){$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_closing_packets (public_id,round_id,investor_user_id,packet_name,status,external_packet_reference,notes,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute([$publicId,(int)$round['id'],$userId,mg_investment_text($input['packet_name']??'',220,2,'Packet name'),$status,mg_investment_text($input['external_packet_reference']??'',220)?:null,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,$actorId]);}else{$q=$pdo->prepare('SELECT id FROM investment_closing_packets WHERE public_id=? AND round_id=? LIMIT 1');$q->execute([mg_investment_text($publicId,36,36,'Packet identifier'),(int)$round['id']]);$id=(int)$q->fetchColumn();if($id<1)throw new MgInvestmentException('Closing packet not found.',404);$pdo->prepare('UPDATE investment_closing_packets SET packet_name=?,status=?,external_packet_reference=?,notes=?,updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([mg_investment_text($input['packet_name']??'',220,2,'Packet name'),$status,mg_investment_text($input['external_packet_reference']??'',220)?:null,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,$id]);}mg_audit('investment_closing_packet_saved','investment_closing_packet',['packet_id'=>$publicId,'round_id'=>$round['public_id'],'investor_user_id'=>$userId],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$round['public_id']]);
}

function mg_investment_packet_document_save(PDO $pdo,array $actor,array $input): array
{
    mg_investment_require_permission($actor,'admin.investment.closing.manage');$q=$pdo->prepare('SELECT p.*,r.public_id AS round_public_id FROM investment_closing_packets p INNER JOIN investment_rounds r ON r.id=p.round_id WHERE p.public_id=? LIMIT 1');$q->execute([mg_investment_text($input['packet_id']??'',36,36,'Packet identifier')]);$packet=$q->fetch(PDO::FETCH_ASSOC);if(!$packet)throw new MgInvestmentException('Closing packet not found.',404);$types=['investor_questionnaire','subscription_agreement','safe_or_note','accreditation_evidence','tax_form','side_letter','board_consent','countersigned_agreement','funding_confirmation','closing_certificate','form_d_receipt','state_notice_receipt','other'];$statuses=['not_started','requested','received','review','approved','executed','complete','rejected','expired','not_applicable'];$investorSig=['not_required','not_started','sent','signed','declined'];$companySig=['not_required','not_started','signed'];$counsel=['not_required','not_started','in_review','approved','changes_required'];$type=(string)($input['document_type']??'other');$status=(string)($input['status']??'not_started');if(!in_array($type,$types,true)||!in_array($status,$statuses,true)||!in_array($input['investor_signature_status']??'not_started',$investorSig,true)||!in_array($input['company_signature_status']??'not_started',$companySig,true)||!in_array($input['counsel_status']??'not_started',$counsel,true))throw new MgInvestmentException('Invalid closing document status.');$publicId=trim((string)($input['document_id']??''));$actorId=(int)$actor['id'];$url=mg_investment_url($input['external_url']??'');if(in_array($status,['executed','complete'],true)&&$url===null)throw new MgInvestmentException('Executed or complete document records require an approved external reference URL.');if($publicId===''){$publicId=mg_investment_uuid();$pdo->prepare('INSERT INTO investment_closing_documents (public_id,packet_id,document_type,title,status,required_document,external_url,version_number,investor_signature_status,company_signature_status,counsel_status,expires_at,completed_at,notes,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,IF(? IN ("executed","complete","not_applicable"),NOW(),NULL),?,?,?,NOW(),NOW())')->execute([$publicId,(int)$packet['id'],$type,mg_investment_text($input['title']??'',220,2,'Document title'),$status,mg_investment_bool($input['required_document']??true)?1:0,$url,max(1,(int)($input['version_number']??1)),$input['investor_signature_status']??'not_started',$input['company_signature_status']??'not_started',$input['counsel_status']??'not_started',mg_investment_date($input['expires_at']??null),$status,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,$actorId]);}else{$d=$pdo->prepare('SELECT id FROM investment_closing_documents WHERE public_id=? AND packet_id=? LIMIT 1');$d->execute([mg_investment_text($publicId,36,36,'Document identifier'),(int)$packet['id']]);$id=(int)$d->fetchColumn();if($id<1)throw new MgInvestmentException('Closing document not found.',404);$pdo->prepare('UPDATE investment_closing_documents SET document_type=?,title=?,status=?,required_document=?,external_url=?,version_number=?,investor_signature_status=?,company_signature_status=?,counsel_status=?,expires_at=?,completed_at=IF(? IN ("executed","complete","not_applicable"),COALESCE(completed_at,NOW()),NULL),notes=?,updated_by_user_id=?,updated_at=NOW() WHERE id=?')->execute([$type,mg_investment_text($input['title']??'',220,2,'Document title'),$status,mg_investment_bool($input['required_document']??true)?1:0,$url,max(1,(int)($input['version_number']??1)),$input['investor_signature_status']??'not_started',$input['company_signature_status']??'not_started',$input['counsel_status']??'not_started',mg_investment_date($input['expires_at']??null),$status,mg_investment_long_text($input['notes']??'',8000)?:null,$actorId,$id]);}mg_investment_packet_recalculate($pdo,(int)$packet['id']);mg_investment_pipeline_activity($pdo,(int)$packet['investor_user_id'],(int)$packet['round_id'],'commitment_update','Closing document updated',mg_investment_text($input['title']??'',220),$actorId,['document_type'=>$type,'status'=>$status]);mg_audit('investment_closing_document_saved','investment_closing_document',['document_id'=>$publicId,'packet_id'=>$packet['public_id'],'status'=>$status],$actorId);return mg_investment_closing_dashboard($pdo,['round_id'=>$packet['round_public_id']]);
}
